/// <summary>
/// This <c>METSOPrintDestinationController</c> class used for print destination settings
/// </summary>
class METSOPrintDestinationController extends SysOperationServiceController implements BatchRetryable
{
    #AssetTransfer

}

Method.Source:
/// <summary>
/// Static method to initiate the call to <c>METSOPrintDestinationController</c> class.
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METSOPrintDestinationController      controller =  new METSOPrintDestinationController();

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.startOperation();

    if (!controller.isDialogCancelled())
    {
        METSOPrintDestinationContract contract = controller.getDataContractObject('_contract') as METSOPrintDestinationContract;

        // This code is written If user want to open report in screen or file.
        if (controller.parmExecutionMode() != SysOperationExecutionMode::ScheduledBatch)
        {
            sRSPrintDestinationSettings sRSPrintDestinationSettings =
                                            controller.getDataContractObject('SRSPrintDestinationSettings')
                                                                            as SRSPrintDestinationSettings;
            contract.parmRecordCon(str2con(_args.parm()));
            contract.parmMenuItemName(_args.menuItemName());
            METSOPrintDestinationService::loopRecords(contract, sRSPrintDestinationSettings);
        }
    }
}

/// <summary>
/// Creates a new instance of the <c>METSOPrintDestinationController</c> class.
/// </summary>
public void new()
{
    super(classStr(METSOPrintDestinationService), methodStr(METSOPrintDestinationService, process));

    this.parmDialogCaption('@MET:PrintMutltiReports');
}

/// <summary>
/// Post run method
/// </summary>
protected void dialogPostRun()
{
    super();

    this.updateDesign();
}

/// <summary>
/// method returns boolean value based on the dialog form cancelled or not
/// </summary>
/// <returns>boolean</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}

/// <summary>
/// method returns true if can run in new session
/// </summary>
/// <returns>boolean</returns>
protected boolean canRunInNewSession()
{
    return true;
}

/// <summary>
/// method to set printsetting visible
/// </summary>
/// <returns>boolean</returns>
public boolean showPrintSettings()
{
    return true;
}

/// <summary>
/// This method we are enable the group.
/// </summary>
public void updateDesign()
{
    FormRun                     formRun;
    FormBuildGroupControl       groupBuildControl;
    FormGroupControl            groupControl;
    SysOperationDialog          sysOperationDialog;

    sysOperationDialog  = dialog as SysOperationDialog;
    formRun             = sysOperationDialog.formRun();

    groupBuildControl   = formRun.form().design().control(#CurrentPrintDestinationControlName);
    groupControl        = formRun.design().control(groupBuildControl.id());
    groupControl.visible(true);
}

/// <summary>
/// Validate and return the boolean value
/// </summary>
/// <returns>boolean</returns>
protected boolean validate()
{
    boolean     isValid;

    isValid = super() && this.validateReportPrintSetting();

    return isValid;
}

/// <summary>
/// method to validate is report run in batch and return boolean
/// </summary>
/// <returns>boolean</returns>
private boolean validateReportPrintSetting()
{
    boolean                     isValid = true;
    SRSPrintDestinationSettings printSettings;

    if (this.batchInfo() && this.batchInfo().parmBatchExecute())
    {
        printSettings = this.getDataContractObject('SRSPrintDestinationSettings') as SRSPrintDestinationSettings;

        if (printSettings && printSettings.printMediumType() == SRSPrintMediumType::Screen)
        {
            isValid = checkFailed("@SYS329665");
        }
    }

    return isValid;
}

/// <summary>
/// returns true if retryable true
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}
